/**
 * Build a roof. footprint: the WALL footprint (outer faces) as a rect or union of rects. opts:
 *   y            the eave course (wall top + 1)                                    (required)
 *   material     a palette ("slate", "spruce-shingle", ...), a block (mixed by autoMix) or { mix:[[block,w]..], eave, ridge, verge .. }
 *   texture      false = the one named block only (a guard-rail warning)   trim   cornice / verge / dentil material
 *   pitch        half | 45 | steep | very-steep | number                  overhang 0..2, or { north, south, east, west } (default 1)
 *   eave         plain | flared | cornice                                  soffit  slab material under the overhang
 *   ridge        slab | wall | crest | rods | none | a block name          ridgeAxis "x" | "z" (gable wings; default the long side)
 *   gable        gable-end wall block (default: the wall block under the eave)   verge  barge-course material
 *   hips         material for the hip stairs                               pattern { material, every, offset }
 *   lower, upperPitch  (mansard, gambrel)                                  low     the low side of a shed
 *   dormers      { face (a side, "all" or a list), count | every, style: gable|shed|eyebrow, width, height, window, wall }
 *   pediment     { face, width, pitch, tympanum, oculus } (face string also works)
 *   chimneys     [[x,z] | { at, size, material, rise }]   (rise from the local roof surface, default 2)
 *   tower        { at:[x,z], size, height, top: lantern|spire|cap, material, from }
 *   edges        false | { fascia, soffit, barge } (default all on when the overhang is 1+): an open-trapdoor fascia on the
 *                outer face of the eave, soffit slabs under the overhang, a barge course on gable ends. fascia: a block name.
 *   maxHeight    roof height cap in courses: the pitch steps down 3 > 2 > 1 > 0.5 until it fits
 *   cantilever   (flat-parapet) extend the deck by the overhang, with a fascia and soffit
 *   materialAt   ({ x, z, course, courses, role, full }) -> block name; role: field|eave|ridge|verge|hip|fascia|soffit
 *   heightMod    (H, info) -> { puts } mutate the height map (Map "x,z" -> blocks above the eave); puts: [[x, dy, z, [block, state]]]
 *   dryRun       compute everything, write nothing: returns { dryRun: true, facts, notes }
 *   keep         [{from:[x,y,z], to:[x,y,z]}] never written; protect: Set "x,y,z" (default: the grid's functional cells)
 *   grow         grow the grid to fit (default true)
 * Returns { cells, refused, shift, eave: y, top, footprint, notes, facts }.
 */
export function roof(g, footprint, style = "hip", o = {}) {
  if (ROOF_PRESETS[style] || o.preset) {                                   // a preset: good options by construction, flags override
    const name = ROOF_PRESETS[style] ? style : o.preset, { preset, ...rest } = o;
    if (!ROOF_PRESETS[name]) throw new Error(`roof: unknown preset ${name} (${Object.keys(ROOF_PRESETS).join(", ")})`);
    const [x, z] = XZ(k);
    let m = Infinity;
    for (const [a, b, c, d] of rects) m = Math.min(m, Math.max(a - x, x - c, 0, b - z, z - d));
    return -m;
  };
  const gabled = ["gable", "gambrel", "shed", "dutch-gable"].includes(style);
  const ped = o.pediment ? (typeof o.pediment === "string" ? { face: o.pediment } : o.pediment) : null;
  let pedInfo = null, modPuts = [];
  const heights = (P) => {
    const rise = riseFn(style, P, o, span), hipH = (k) => rise(dWall(k)), H = new Map(), axis = new Map(), owner = new Map();
    const rectGable = (r, x, z, ax) => {
      const [a, b, c, d] = r;
      if (style === "shed") { const low = o.low ?? "south"; return rise(low === "south" ? d - z : low === "north" ? z - b : low === "east" ? c - x : x - a); }
      return rise(ax === "x" ? Math.min(z - b, d - z) : Math.min(x - a, c - x));
    };
    for (const k of M) {
      const [x, z] = XZ(k);
      let h = -Infinity, ax = null, own = null;
      if (style === "hip" || style === "pyramid" || style === "mansard") { h = hipH(k); }
      else for (const r of rects) {
        if (x < r[0] - ovS.west || x > r[2] + ovS.east || z < r[1] - ovS.north || z > r[3] + ovS.south) continue;
        const rax = o.ridgeAxis ?? (style === "shed" ? (["east", "west"].includes(o.low) ? "z" : "x") : r[2] - r[0] >= r[3] - r[1] ? "x" : "z");
        let v = rectGable(r, x, z, rax);
        if (style === "dutch-gable") {                                       // gablet set back from each end over a hip
          const len = rax === "x" ? r[2] - r[0] + 1 : r[3] - r[1] + 1, inset = o.inset ?? Math.max(2, Math.round(len / 4));
          const along = rax === "x" ? Math.min(x - r[0], r[2] - x) : Math.min(z - r[1], r[3] - z);
          v = along >= inset ? Math.max(v, hipH(k)) : hipH(k);
        }
        if (v > h) { h = v; ax = rax; own = r; }
      }
      H.set(k, h); axis.set(k, ax); owner.set(k, own);
    }
    // the pediment: a cross-gable on one face, ridge perpendicular to it, tympanum in its gable end
    pedInfo = null;
    if (ped) {
      const R = R0, f = ped.face, lat = ZD.has(f) ? [R[0], R[2]] : [R[1], R[3]], mid = (lat[0] + lat[1]) / 2;
      let pw = ped.width ?? Math.round((lat[1] - lat[0] + 1) * 0.55); if (pw % 2 !== (lat[1] - lat[0] + 1) % 2) pw++;
      const l0 = Math.round(mid - (pw - 1) / 2), l1 = Math.round(mid + (pw - 1) / 2), pp = pitchOf(ped.pitch ?? 45);
      pedInfo = { face: f, l0, l1, pp, R };
      const pax = ZD.has(f) ? "z" : "x";
      const wl = { north: R[1], south: R[3], west: R[0], east: R[2] }[f], depth = ped.depth ?? Math.floor(((ZD.has(f) ? R[3] - R[1] : R[2] - R[0]) + 1) / 2);
      for (const k of M) {
        const [x, z] = XZ(k), l = ZD.has(f) ? x : z, inward = (ZD.has(f) ? z - wl : x - wl) * (f === "north" || f === "west" ? 1 : -1);
        if (l < l0 - ov || l > l1 + ov || inward > depth) continue;              // the front half only
        const v = (Math.min(l - (l0 - ov), l1 + ov - l) - ov) * pp;
        if (v > H.get(k) + 0.01) { H.set(k, v); axis.set(k, pax); owner.set(k, "ped"); }
      }
    }
    modPuts = [];
    if (heightMod) {                                                         // the caller's last word on the height map (eave:"upturned" supplies upturn())
      const r = heightMod(H, { M, M0, ov, ovSides: { ...ovS }, rects, axis, owner, style, P, y0, rise });
      if (r?.puts) modPuts = r.puts;
    }
    return { H, axis, owner };
  };
  const maxHeight = o.maxHeight ?? (o.pitch == null && wallH > 0 ? Math.max(1, Math.floor(ratioCap(style, o._preset, wallH) * wallH)) : null);   // no explicit pitch: the roof stays within its ratio cap
